namespace cobalt = webcpp::cobalt;
namespace beast = webcpp::beast;

using executor_type = cobalt::use_op_t::executor_with_default<cobalt::executor>;
using socket_type = webcpp::asio::ip::tcp::socket::rebind_executor<executor_type>::other;
using ssl_socket_type = webcpp::asio::ssl::stream<socket_type>;
using acceptor_type = webcpp::asio::ip::tcp::acceptor::rebind_executor<executor_type>::other;
using websocket_type = beast::websocket::stream<ssl_socket_type>;

namespace {

cobalt::promise<ssl_socket_type> connect(std::string_view host, webcpp::asio::ssl::context& ctx) {
    webcpp::asio::ip::tcp::resolver resolve{cobalt::this_thread::get_executor()};
    auto const endpoints =
        co_await resolve.async_resolve("127.0.0.1", webcpp_fixture::remote_port(), cobalt::use_op);

    // Timer for timeouts

    ssl_socket_type sock{cobalt::this_thread::get_executor(), ctx};
    sock.set_verify_mode(webcpp::asio::ssl::verify_peer);
    sock.set_verify_callback(webcpp::asio::ssl::host_name_verification("localhost"));
    if (SSL_set_tlsext_host_name(sock.native_handle(), "localhost") != 1) {
        std::abort();
    }
    printf("connecting\n");

    co_await sock.next_layer().async_connect(*endpoints.begin());
    printf("connected\n");

    // Connected, now do the handshake
    printf("handshaking\n");
    co_await sock.async_handshake(webcpp::asio::ssl::stream_base::client);
    printf("hand shook\n");
    co_return sock;
}

}  // namespace

cobalt::main co_main(int argc, char** argv) {
    webcpp::asio::ssl::context ctx{webcpp::asio::ssl::context::tls_client};
    ctx.load_verify_file(webcpp_fixture::ca_file());
    auto conn = co_await connect("boost.org", ctx);
    printf("connected\n");
    beast::http::request<beast::http::empty_body> req{beast::http::verb::get, "/index.html", 11};
    req.set(beast::http::field::host, "boost.org");
    co_await beast::http::async_write(conn, req, cobalt::use_op);

    // read the response
    beast::flat_buffer b;
    beast::http::response<beast::http::string_body> response;
    co_await beast::http::async_read(conn, b, response, cobalt::use_op);

    // write the response
    printf("%s\n", response.body().c_str());
    co_return 0;
}
